/**
 * Resolve any book title string (e.g. "Cambridge Primary Paths 3", "CPP 2",
 * "Primary Path 1") to a canonical book ID ("CPP1", "CPP2", "CPP3") or null.
 */
export function resolveCoursebookId(bookTitle) {
  const raw = String(bookTitle || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!raw) return null;
  for (const [id, meta] of Object.entries(CPP_BOOKS)) {
    if (meta.aliases.some((a) => raw === a || raw.includes(a))) return id;
  }
  const m = raw.match(/primary\s*paths?\s*([123])\b/i) || raw.match(/\bcpp\s*([123])\b/i);
  if (m) return `CPP${m[1]}`;
  return null;
}

/**
 * Compute exact Student's Book & Workbook page boundaries and section presets
 * for a given unit (1..9) of Cambridge Primary Path 1, 2, or 3.
 */
export function getCppUnitStructure(bookId, unitNum) {
  const u = Number(unitNum);
  if (!bookId || !CPP_BOOKS[bookId] || !Number.isInteger(u) || u < 1 || u > 9) return null;
  const sbStart = 6 + (u - 1) * 22;
  const sbEnd = sbStart + 21;
  const wbStart = 3 + (u - 1) * 10;
  const wbEnd = wbStart + 9;
  const unitMeta = CPP_BOOKS[bookId].units[u] || { title: `Unit ${u}`, theme: "" };

  return {
    bookId,
    bookTitle: CPP_BOOKS[bookId].title,
    recommendedProfile: CPP_BOOKS[bookId].recommendedProfile,
    cefr: CPP_BOOKS[bookId].cefr,
    unit: u,
    unitTitle: unitMeta.title,
    unitTheme: unitMeta.theme,
    nonfictionTitle: unitMeta.nonfiction || "",
    fictionTitle: unitMeta.fiction || "",
    sbStart,
    sbEnd,
    wbStart,
    wbEnd,
    sections: [
      {
        id: "FULL",
        label: `Full Unit ${u} (p. ${sbStart}–${sbEnd})`,
        shortLabel: "Full Unit",
        pageRange: `${sbStart}–${sbEnd}`,
        startPage: sbStart,
        endPage: sbEnd,
        wbRange: `WB p. ${wbStart}–${wbEnd}`,
      },
      {
        id: "BQ",
        label: `Big Question (p. ${sbStart}–${sbStart + 1})`,
        shortLabel: "Big Question",
        pageRange: `${sbStart}–${sbStart + 1}`,
        startPage: sbStart,
        endPage: sbStart + 1,
        wbRange: `WB p. ${wbStart}`,
      },
      {
        id: "A_READ",
        label: `${u}A Nonfiction Reading (p. ${sbStart + 2}–${sbStart + 5})`,
        shortLabel: `${u}A Reading (p. ${sbStart + 2}–${sbStart + 5})`,
        pageRange: `${sbStart + 2}–${sbStart + 5}`,
        startPage: sbStart + 2,
        endPage: sbStart + 5,
        wbRange: `WB p. ${wbStart}–${wbStart + 2}`,
      },
      {
        id: "A_FULL",
        label: `${u}A Complete Section (p. ${sbStart}–${sbStart + 9})`,
        shortLabel: `${u}A Full (p. ${sbStart}–${sbStart + 9})`,
        pageRange: `${sbStart}–${sbStart + 9}`,
        startPage: sbStart,
        endPage: sbStart + 9,
        wbRange: `WB p. ${wbStart}–${wbStart + 4}`,
      },
      {
        id: "B_READ",
        label: `${u}B Fiction Reading (p. ${sbStart + 10}–${sbStart + 15})`,
        shortLabel: `${u}B Reading (p. ${sbStart + 10}–${sbStart + 15})`,
        pageRange: `${sbStart + 10}–${sbStart + 15}`,
        startPage: sbStart + 10,
        endPage: sbStart + 15,
        wbRange: `WB p. ${wbStart + 5}–${wbStart + 7}`,
      },
      {
        id: "B_FULL",
        label: `${u}B Complete + Speaking Mission (p. ${sbStart + 10}–${sbEnd})`,
        shortLabel: `${u}B Full (p. ${sbStart + 10}–${sbEnd})`,
        pageRange: `${sbStart + 10}–${sbEnd}`,
        startPage: sbStart + 10,
        endPage: sbEnd,
        wbRange: `WB p. ${wbStart + 5}–${wbEnd}`,
      },
    ],
  };
}

/**
 * Parse a flexible page range string (e.g. "118–120", "118-125", "p. 118, 120",
 * "WB 53-57", "8") into numeric page intervals and detect whether the user
 * explicitly typed "WB" / "Workbook".
 */
export function parsePageRangeSpec(pageRangeStr) {
  const raw = String(pageRangeStr || "").trim();
  if (!raw) return { hasPages: false, intervals: [], explicitWb: false, minPage: null, maxPage: null };

  const explicitWb = /\b(wb|workbook)\b/i.test(raw);
  const cleaned = raw
    .replace(/\b(wb|workbook|sb|student'?s?\s*book|pages?|pp?\.?)\b/gi, " ")
    .replace(/[–—−~]/g, "-");

  const intervals = [];
  const parts = cleaned.split(/[,;&]+/).map((s) => s.trim()).filter(Boolean);
  for (const part of parts) {
    const rangeMatch = part.match(/(\d+)\s*-\s*(\d+)/);
    if (rangeMatch) {
      const a = Number(rangeMatch[1]);
      const b = Number(rangeMatch[2]);
      intervals.push([Math.min(a, b), Math.max(a, b)]);
      continue;
    }
    const nums = part.match(/\d+/g);
    if (nums && nums.length === 1) {
      const n = Number(nums[0]);
      intervals.push([n, n]);
    } else if (nums && nums.length >= 2) {
      const a = Number(nums[0]);
      const b = Number(nums[nums.length - 1]);
      intervals.push([Math.min(a, b), Math.max(a, b)]);
    }
  }

  if (!intervals.length) {
    return { hasPages: false, intervals: [], explicitWb, minPage: null, maxPage: null };
  }
  const minPage = Math.min(...intervals.map((i) => i[0]));
  const maxPage = Math.max(...intervals.map((i) => i[1]));
  return { hasPages: true, intervals, explicitWb, minPage, maxPage };
}

/**
 * Given a Student's Book (or Workbook) page number in CPP 1/2/3, infer which
 * Unit (1..9) it belongs to.
 */
export function inferUnitFromPages(bookId, pageRangeStr) {
  if (!bookId || !CPP_BOOKS[bookId]) return null;
  const parsed = parsePageRangeSpec(pageRangeStr);
  if (!parsed.hasPages || parsed.minPage === null) return null;

  const p = parsed.minPage;
  if (parsed.explicitWb) {
    if (p >= 3 && p <= 92) {
      return Math.min(9, Math.max(1, Math.floor((p - 3) / 10) + 1));
    }
    return null;
  }
  if (p >= 6 && p <= 203) {
    return Math.min(9, Math.max(1, Math.floor((p - 6) / 22) + 1));
  }
  return null;
}

/**
 * Query the Coursebook Wordbank with smart filtering:
 * - bookTitle or bookId ("CPP1", "CPP2", "CPP3")
 * - unit (1..9; if omitted, inferred from pageRange when possible)
 * - pageRange (optional e.g. "118–121"; filters SB words to those pages and
 *   maps WB words either by matching section/pages or entire unit)
 * - includeSb (default true)
 * - includeWb (default true)
 * - wbScope: "section" (matches WB words belonging to the active SB section/pages)
 *            or "unit" (includes all WB words of the unit across any pages of that unit)
 * - includeEnriched (default true — includes 2nd Edition / CEFR Booster words)
 * - hideBasic (default true — filters out ultra-trivial sight words like "I, you, big, cat")
 */
export function queryCoursebookWords(options = {}) {
  const bookId = options.bookId || resolveCoursebookId(options.bookTitle);
  if (!bookId || !CPP_BOOKS[bookId]) {
    return { supported: false, bookId: null, unit: null, words: [], counts: { sb: 0, wb: 0, enriched: 0, total: 0 } };
  }

  const parsedPages = parsePageRangeSpec(options.pageRange);
  let unit = Number(options.unit) || 0;
  if ((!unit || unit < 1 || unit > 9) && parsedPages.hasPages) {
    unit = inferUnitFromPages(bookId, options.pageRange) || 0;
  }

  const includeSb = options.includeSb !== false;
  const includeWb = options.includeWb !== false;
  const wbScope = options.wbScope || "unit"; // "unit" (all WB words for the unit) or "section" (mapped to selected SB pages)
  const includeEnriched = options.includeEnriched !== false;
  const hideBasic = options.hideBasic !== false;

  const pageMatchesIntervals = (p, intervals) =>
    intervals.some(([a, b]) => p >= a && p <= b);

  // Determine which sections ("A", "B") are touched if a Student's Book page range is given
  const unitStruct = unit >= 1 && unit <= 9 ? getCppUnitStructure(bookId, unit) : null;
  let touchesSectionA = true;
  let touchesSectionB = true;
  if (unitStruct && parsedPages.hasPages && !parsedPages.explicitWb) {
    const secAEnd = unitStruct.sbStart + 9;
    const secBStart = unitStruct.sbStart + 10;
    touchesSectionA = parsedPages.intervals.some(([a, b]) => a <= secAEnd && b >= unitStruct.sbStart);
    touchesSectionB = parsedPages.intervals.some(([a, b]) => b >= secBStart && a <= unitStruct.sbEnd);
  }

  const candidates = CPP_WORDBANK.filter((entry) => {
    if (entry.bookId !== bookId) return false;
    if (unit >= 1 && unit <= 9 && entry.unit !== unit) return false;
    if (hideBasic && entry.isBasic) return false;

    if (entry.source === "sb") {
      if (!includeSb) return false;
      if (parsedPages.hasPages && !parsedPages.explicitWb) {
        return pageMatchesIntervals(entry.sbPage, parsedPages.intervals);
      }
      if (parsedPages.hasPages && parsedPages.explicitWb) {
        return false;
      }
      return true;
    }

    if (entry.source === "wb") {
      if (!includeWb) return false;
      if (parsedPages.hasPages && parsedPages.explicitWb) {
        return pageMatchesIntervals(entry.wbPage, parsedPages.intervals);
      }
      if (parsedPages.hasPages && wbScope === "section") {
        // Match WB words that map to the selected SB pages OR belong to the active section (A/B)
        if (pageMatchesIntervals(entry.sbPage, parsedPages.intervals)) return true;
        if (touchesSectionA && !touchesSectionB) return entry.wbSubSection === "A";
        if (touchesSectionB && !touchesSectionA) return entry.wbSubSection === "B";
      }
      return true;
    }

    if (entry.source === "enriched") {
      if (!includeEnriched) return false;
      if (parsedPages.hasPages && !parsedPages.explicitWb) {
        if (pageMatchesIntervals(entry.sbPage, parsedPages.intervals)) return true;
        if (touchesSectionA && !touchesSectionB) return entry.section === "A";
        if (touchesSectionB && !touchesSectionA) return entry.section === "B";
        return false;
      }
      return true;
    }

    return false;
  });

  // Deduplicate by lowercase English headword while preferring richer metadata
  const seen = new Map();
  for (const item of candidates) {
    const key = item.english.toLowerCase().trim();
    if (!seen.has(key)) {
      seen.set(key, { ...item });
    } else {
      const prev = seen.get(key);
      if (!prev.derivatives && item.derivatives) prev.derivatives = item.derivatives;
      if (!prev.synonyms && item.synonyms) prev.synonyms = item.synonyms;
      if (!prev.antonyms && item.antonyms) prev.antonyms = item.antonyms;
    }
  }

  const deduped = Array.from(seen.values());
  const counts = {
    sb: deduped.filter((w) => w.source === "sb").length,
    wb: deduped.filter((w) => w.source === "wb").length,
    enriched: deduped.filter((w) => w.source === "enriched").length,
    total: deduped.length,
  };

  return {
    supported: true,
    bookId,
    bookTitle: CPP_BOOKS[bookId].title,
    recommendedProfile: CPP_BOOKS[bookId].recommendedProfile,
    cefr: CPP_BOOKS[bookId].cefr,
    unit: unit || null,
    hasPageFilter: parsedPages.hasPages,
    unitStructure: unitStruct,
    words: deduped,
    counts,
  };
}

/**
 * Pedagogically rank and select up to `maxCount` words when a large unit or
 * section list is capped (balancing Student's Book, Workbook, and 2nd Ed.
 * Enriched words while prioritizing content words with rich word families).
 */
export function selectSmartCoursebookWords(words, maxCount = 0) {
  if (!Array.isArray(words) || !words.length) return [];
  const cap = Number(maxCount) || 0;
  if (cap <= 0 || words.length <= cap) return [...words];

  const scoreWord = (w, idx) => {
    let s = 0;
    if (!w.isBasic) s += 20;
    if (w.source === "enriched") s += 16;
    if (w.source === "wb") s += 8;
    if (w.derivatives) s += 12;
    if (w.synonyms) s += 8;
    if (w.antonyms) s += 8;
    if (["n.", "v.", "adj.", "phr. v."].includes(w.type)) s += 10;
    if (w.english.length >= 5) s += 6;
    // Slight spread bonus across the unit so both Section A and Section B are represented
    s += (idx % 5);
    return s;
  };

  const indexed = words.map((w, idx) => ({ w, idx, score: scoreWord(w, idx) }));
  indexed.sort((a, b) => b.score - a.score || a.idx - b.idx);
  const picked = indexed.slice(0, cap).sort((a, b) => a.idx - b.idx);
  return picked.map((x) => x.w);
}

/**
 * Look up a single English word/phrase in the Coursebook Wordbank, preferring
 * matches from the active book & unit.
 */
export function lookupCoursebookWord(english, bookTitleOrId = "", unitNum = 0) {
  const key = String(english || "").trim().toLowerCase();
  if (!key) return null;
  const bookId = CPP_BOOKS[bookTitleOrId] ? bookTitleOrId : resolveCoursebookId(bookTitleOrId);
  const u = Number(unitNum) || 0;

  if (bookId && u >= 1 && u <= 9) {
    const exactUnit = CPP_WORDBANK.find(
      (e) => e.bookId === bookId && e.unit === u && e.english.toLowerCase().trim() === key
    );
    if (exactUnit) return exactUnit;
  }
  if (bookId) {
    const exactBook = CPP_WORDBANK.find(
      (e) => e.bookId === bookId && e.english.toLowerCase().trim() === key
    );
    if (exactBook) return exactBook;
  }
  return CPP_WORDBANK.find((e) => e.english.toLowerCase().trim() === key) || null;
}
